from content_lib import *

UNITS = []

def irr_lesson(n, pairs, ex):
    """lesson for a group of irregular verbs"""
    formula = " · ".join(f"{a} → {b}" for a, b in pairs[:5]) + " …"
    return lesson(f"Irregular verbs {n}", f"Неправильні дієслова {n}", f"Неправильные глаголы {n}",
        rule(formula, "Ці дієслова в минулому мають власну форму — без -ed. Її треба запам'ятати. Форма однакова для всіх: I went, she went.",
             "Эти глаголы в прошедшем имеют свою форму — без -ed. Её нужно запомнить. Форма одинакова для всех: I went, she went.",
             [(f"{a} → {b}", f"минула форма: {b}", f"прошедшая форма: {b}") for a, b in pairs[:3]]),
        [M(pairs[:4], "Перша форма → минула.", "Первая форма → прошедшая.", tp="past-irregular"),
         M(pairs[4:8], "Перша форма → минула.", "Первая форма → прошедшая.", tp="past-irregular")] + ex)

# ============ 01. Past Simple: неправильные глаголы ============
G1 = [("go", "went"), ("have", "had"), ("see", "saw"), ("make", "made"), ("come", "came"), ("get", "got"), ("take", "took"), ("do", "did"), ("say", "said"), ("know", "knew")]
G2 = [("eat", "ate"), ("drink", "drank"), ("buy", "bought"), ("think", "thought"), ("give", "gave"), ("find", "found"), ("leave", "left"), ("meet", "met"), ("sleep", "slept"), ("write", "wrote")]
